INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1501, 'Exodus 1:18', 'Exodus', 1, 18, '&nbsp;نو بادشاه دايڼې راوغوښتلې او د هغوئ نه يې تپوس وکړو، ”تاسو ولې داسې کوئ؟ تاسو نران بچى ولې ژوندى پرېږدئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1502, 'Exodus 1:19', 'Exodus', 1, 19, '&nbsp;هغوئ هغۀ ته ووئيل، ”عبرانۍ ښځې د مِصريانو ښځو په شان نۀ دى، د دوئ په آسانۍ سره بچى پېدا کيږى او هلته زمونږ د رسېدو نه مخکښې د دوئ ماشومان پېدا شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1503, 'Exodus 1:22', 'Exodus', 1, 22, '&nbsp;په آخر کښې فِرعون خپلو ټولو خلقو له حُکم ورکړو چې، ”د عبرانيانو هر يو پېدا شوے بچے راوړئ او د نيل درياب کښې يې وغورزوئ، خو جينکۍ به ژوندۍ پرېږدئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1504, 'Exodus 2:1', 'Exodus', 2, 1, '&nbsp;په دې دوران کښې د ليوى قبيلې يو سړى په خپله قبيله کښې يوه ښځه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1505, 'Exodus 2:2', 'Exodus', 2, 2, '&nbsp;او د هغې نه د هغۀ يو زوئ وشو. هغې وليدل چې دا ښۀ ښکلے ماشوم وو، نو هغې دا درې مياشتې پټ وساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1506, 'Exodus 2:3', 'Exodus', 2, 3, '&nbsp;خو چې کله هغې دا نور نۀ شو پټولے، هغې د لوخو نه جوړه شوې يوه ټوکرۍ راواخستله او په دې يې تارکول ولګول چې اوبۀ په کښې دننه نۀ ځى. هغې ماشوم په دې کښې کښېنولو او دا يې بيا د درياب په غاړه په لوخو کښې کېښوده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1507, 'Exodus 2:4', 'Exodus', 2, 4, '&nbsp;د ماشوم خور لږه لرې ولاړه وه او کتل يې چې په هغۀ به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1508, 'Exodus 2:5', 'Exodus', 2, 5, '&nbsp;د فِرعون لور لامبلو له د درياب غاړې له راغله، د هغې خِدمتګارې هم د درياب په غاړه روانې وې نو ناڅاپه هغې په لوخو کښې هغه ټوکرۍ وليدله او يوه خِدمتګاره يې ورولېږله چې هغې ته يې را وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1509, 'Exodus 2:6', 'Exodus', 2, 6, '&nbsp;د فِرعون لور ټوکرۍ کولاو کړه او يو ماشوم يې په کښې وليدو. هغۀ ژړل او د هغې ورباندې زړۀ وسوزېدلو. هغې ووئيل، ”دا ماشوم عبرانے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1510, 'Exodus 2:7', 'Exodus', 2, 7, '&nbsp;بيا د هغۀ خور د فِرعون د لور نه تپوس وکړو، ”زۀ يو عبرانۍ ښځه راوغواړم څۀ چې دې ماشوم له سينه ورکوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1511, 'Exodus 2:8', 'Exodus', 2, 8, '&nbsp;هغې ورته ووئيل، ”آو، لاړه شه.“ نو هغه جينۍ لاړه او د ماشوم خپله مور يې راوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1512, 'Exodus 2:9', 'Exodus', 2, 9, '&nbsp;شهزادګۍ دې ښځې ته ووئيل، ”دا ماشوم واخله او زما دپاره سينه ورکوه او زۀ به تا له مزدورى درکوم.“ نو هغې ماشوم يوړو او هغۀ له يې سينه ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1513, 'Exodus 2:10', 'Exodus', 2, 10, '&nbsp;کله چې دا ماشوم لږ لوئ شو نو هغې دا ماشوم د بادشاه لور له ورکړو او د بادشاه لور ماشوم خپل زوئ جوړ کړو. هغې د خپل ځان سره ووئيل، ”ما دا د اوبو نه راوچت کړے دے.“ نو موسىٰ نوم يې ورباندې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1514, 'Exodus 2:11', 'Exodus', 2, 11, '&nbsp;چې کله موسىٰ لوئ شو نو هغه خپلو خلقو عبرانيانو له لاړو او هغۀ وليدل چې د هغوئ نه سخت کار اخستلے شو. هغۀ دا هم وليدل چې يو مِصرى يو عبرانے وهلو، دا د موسىٰ د خپلو خلقو نه يو کس وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1515, 'Exodus 2:12', 'Exodus', 2, 12, '&nbsp;موسىٰ اخوا دېخوا وکتل او چې کله هغۀ ته پته ولګېده چې هيڅ څوک يې هم نۀ ګورى، نو هغه مِصرے يې ووژلو او د هغۀ لاش يې په شګو کښې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1516, 'Exodus 2:13', 'Exodus', 2, 13, '&nbsp;بله ورځ هغه بهر لاړو او وې ليدل چې دوه عبرانيان په خپلو کښې په جګړه وُو. هغۀ هغه يو ته وفرمائيل کوم چې په غلطه وو، ”تۀ ولې خپل عبرانے ورور وهې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1517, 'Exodus 2:14', 'Exodus', 2, 14, '&nbsp;هغه سړى ورته ووئيل، ”تۀ چا په مونږ مشر کړے يې او په مونږ يې قاضى جوړ کړے يې؟ تۀ ما هم وژنې څۀ لکه چې هغه مِصرے دې وژلے وو؟“ نو موسىٰ وويرېدو او د خپل ځان سره يې وفرمائيل، ”ښه نو لکه چې ما څۀ کړى دى د هغې خلقو ته پته لګېدلې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1518, 'Exodus 2:17', 'Exodus', 2, 17, '&nbsp;خو څۀ شپانو د يترو لوڼه وشړلې. نو موسىٰ د هغوئ د بچ کولو دپاره ورَغلو او د هغوئ څاروو له يې اوبۀ ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1519, 'Exodus 2:18', 'Exodus', 2, 18, '&nbsp;چې کله دوئ خپل پلار له راغلې، هغۀ ترې تپوس وکړو، ”تاسو ولې نن ډېر زر راغلئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1520, 'Exodus 2:19', 'Exodus', 2, 19, '&nbsp;هغوئ ورته ووئيل، ”يو مِصرى مونږ د شپانو نه بچ کړُو او هغۀ مونږ له اوبۀ هم راوخېژولې او زمونږ څاروو له يې ورکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1521, 'Exodus 2:20', 'Exodus', 2, 20, '&nbsp;هغۀ د خپلو لوڼو نه تپوس وکړو، ”هغه چرته دے؟ تاسو هغه سړے بهر ولې پرېښودو؟ لاړې شئ او هغه راوغواړئ چې مونږ سره روټۍ وخورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1522, 'Exodus 2:21', 'Exodus', 2, 21, '&nbsp;نو موسىٰ هلته اوسېدو ته راضى شو او يترو هغۀ ته خپله لور صفوره وادۀ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1523, 'Exodus 2:22', 'Exodus', 2, 22, '&nbsp;د هغې نه يې يو زوئ وشو. موسىٰ د خپل ځان سره ووئيل، ”زۀ په دې مُلک کښې مسافر يم.“ نو په هغۀ يې جيرسوم نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1524, 'Exodus 2:23', 'Exodus', 2, 23, '&nbsp;ډېره موده پس چې د مِصر بادشاه مړ شو، خو بنى اِسرائيلو د غلامۍ په وجه فرياد کولو نو هغوئ په چغو وژړل، ”خُدايه پاکه، زمونږ مدد وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1525, 'Exodus 2:24', 'Exodus', 2, 24, '&nbsp;نو خُدائ پاک د دوئ ژړا واورېدله. هغۀ د هغوئ فرياد واورېدو او د اِبراهيم، اِسحاق او يعقوب سره يې خپل هغه لوظ راياد کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1526, 'Exodus 2:25', 'Exodus', 2, 25, '&nbsp;هغۀ د بنى اِسرائيلو تکليف وليدو او ورباندې خفه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1527, 'Exodus 3:1', 'Exodus', 3, 1, '&nbsp;د موسىٰ سخر يترو د ميديان اِمام وو. يوه ورځ چې کله موسىٰ د هغۀ ګډې او چېلۍ څرولې، هغۀ رمه د بيابان نه واړوله او د خُدائ پاک غر سينا ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1528, 'Exodus 3:2', 'Exodus', 3, 2, '&nbsp;هلته هغۀ ته د مالِک خُدائ هغه فرښته د اور لمبې په شان د بوټى د مينځ نه راڅرګنده شوه. چې د موسىٰ پرې څنګه نظر پرېوتو نو په دې ليدو حېران شو چې په جاړه اور لګېدلے وو خو دا نۀ سوزېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1529, 'Exodus 3:3', 'Exodus', 3, 3, '&nbsp;هغۀ د ځان سره وفرمائيل چې، ”عجيبه خبره ده. دا جاړه ولې نۀ سوزيږى؟ زۀ به نزدې ورشم چې وې ګورم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1530, 'Exodus 3:4', 'Exodus', 3, 4, '&nbsp;چې کله مالِک خُدائ وليدل چې موسىٰ نزدې راروان وو، هغه د جاړې مينځ نه ورته آواز ورکړو او ورته يې وفرمائيل، ”موسىٰ! موسىٰ!“ هغۀ ورته وفرمائيل، ”جى زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1531, 'Exodus 3:5', 'Exodus', 3, 5, '&nbsp;خُدائ پاک ورته وفرمائيل، ”نور نزدې مۀ راځه. پېزار وباسه، ځکه چې تۀ په پاکه زمکه ولاړ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1532, 'Exodus 3:6', 'Exodus', 3, 6, '&nbsp;زۀ ستا د پلار نيکونو خُدائ پاک يم، د اِبراهيم، د اِسحاق او د يعقوب خُدائ پاک يم.“ نو موسىٰ خپل مخ پټ کړو، ځکه چې هغه خُدائ پاک ته کتلو نه يرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1533, 'Exodus 3:7', 'Exodus', 3, 7, '&nbsp;بيا مالِک خُدائ ورته وفرمائيل، ”ما وليدل چې زما د خلقو سره په مِصر کښې څومره ظلم کيږى، ما د هغوئ فرياد اورېدلے دے چې هغوئ د ظالمانو مشرانو نه خلاص شى. ما ته د هغوئ د ټولو تکليفونو پته ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1534, 'Exodus 3:8', 'Exodus', 3, 8, '&nbsp;نو زۀ لاندې راغلے يم چې هغوئ د مِصريانو نه خلاص کړم او چې هغوئ د مِصر نه بهر يو ښۀ، کولاو او زرخېز مُلک ته بوځم، چرته چې اوس کنعانيان، حِتيان، اموريان، فرزيان، حِويان او يبوسيان اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1535, 'Exodus 3:9', 'Exodus', 3, 9, '&nbsp;ګوره، ما د خپلو خلقو ژړا اورېدلې ده او زۀ دا هم ګورم چې مِصريان په دوئ ظلم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1536, 'Exodus 3:10', 'Exodus', 3, 10, '&nbsp;اوس زۀ تا فِرعون له لېږم نو تۀ به زما خلق بنى اِسرائيل د مِصر نه بهر بوځې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1537, 'Exodus 3:11', 'Exodus', 3, 11, '&nbsp;خو موسىٰ خُدائ پاک ته وفرمائيل، ”زۀ څوک يم چې فِرعون له ورشم او بنى اِسرائيل د مِصر نه بهر بوځم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1538, 'Exodus 3:12', 'Exodus', 3, 12, '&nbsp;خُدائ پاک ورته وفرمائيل، ”زۀ به ستا مل يم او چې تۀ کله دا خلق د مِصر نه بهر بوځې، نو تۀ به په دې غر دپاسه زما عبادت وکړې. هغه به د دې ثبوت وى چې تۀ ما لېږلے يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1539, 'Exodus 3:13', 'Exodus', 3, 13, '&nbsp;خو موسىٰ ورته وفرمائيل، ”چې کله زۀ بنى اِسرائيلو له ورشم او ورته ووايم، چې زۀ ستاسو د پلار نيکۀ خُدائ پاک تاسو ته رالېږلے يم، هغوئ به زما نه تپوس وکړى چې د هغۀ څۀ نوم دے؟ نو زۀ هغوئ ته څۀ ووايم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1540, 'Exodus 3:14', 'Exodus', 3, 14, '&nbsp;خُدائ پاک ورته وفرمائيل، ”زۀ هغه يم چې يم. تۀ به خامخا هغوئ ته داسې ووائې چې، ”زۀ هغه يم“ تاسو ته رالېږلے يم څوک چې په خپله خپل ځان ته ”زۀ يم“ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1541, 'Exodus 3:15', 'Exodus', 3, 15, '&nbsp;بنى اِسرائيلو ته ووايه چې ما مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک د اِبراهيم، اِسحاق او د يعقوب خُدائ پاک، تۀ هغوئ ته ورلېږلے يې. دا د همېشه دپاره زما نوم دے، راتلونکى نسلونه به ما په دې نوم يادوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1542, 'Exodus 3:16', 'Exodus', 3, 16, '&nbsp;لاړ شه او د بنى اِسرائيلو مشران په يو ځائ راغونډ کړه او هغوئ ته ووايه چې زۀ مالِک خُدائ، د هغوئ د پلار نيکۀ خُدائ پاک، د اِبراهيم، اِسحاق او يعقوب خُدائ پاک، تا ته راڅرګند شوم. هغوئ ته ووايه چې زۀ دوئ له راغلے يم او ما ليدلى دى چې مِصريانو د دوئ سره څۀ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1543, 'Exodus 3:17', 'Exodus', 3, 17, '&nbsp;ما دا فېصله کړې ده چې زۀ به دوئ د مِصر نه بهر بوځم چې په کوم ځائ کښې په دوئ ظلم کيږى او زۀ به دوئ هغه زرخېز مُلک ته بوځم، چې هغه د کنعانيانو، حِتيانو، اموريانو، فرزيانو، حِويانو او د يبوسيانو مُلک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1544, 'Exodus 3:18', 'Exodus', 3, 18, '&nbsp;زما خلق به ستا خبره واورى. نو تۀ د بنى اِسرائيلو مشران د مِصر بادشاه له بوځه او هغۀ ته ووايه چې، مالِک خُدائ د عبرانيانو خُدائ پاک، مونږ ته په خپله ځان څرګند کړو. اوس تۀ مونږ په صحرا کښې د درېو ورځو سفر ته پرېږده چې مالِک خُدائ، زمونږ خُدائ پاک ته قربانۍ پېش کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1545, 'Exodus 3:19', 'Exodus', 3, 19, '&nbsp;ما ته پته ده چې د مِصر بادشاه به تاسو تلو ته پرې نۀ ږدى ترڅو چې هغه مجبور کړے شوے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1546, 'Exodus 3:20', 'Exodus', 3, 20, '&nbsp;خو زۀ به د خپل قُدرت نه کار واخلم او زۀ به هلته د عجيبه عجيبه کارونو کولو په ذريعه مِصريانو له سزا ورکړم. او د هغې نه پس به هغه تاسو تلو ته پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1547, 'Exodus 3:21', 'Exodus', 3, 21, '&nbsp;زۀ به په مِصريانو ستاسو قدر وکړم نو چې کله زما خلق ځى، دوئ به خالى لاسونه نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1548, 'Exodus 3:22', 'Exodus', 3, 22, '&nbsp;هره يوه بنى اِسرائيلۍ ښځه دې خپلو مِصريانو ګاونډيانو کره لاړه شى او هرې مِصرۍ ښځې له چې د دوئ سره په کور کښې اوسيږى نو جامې، د سرو زرو او سپينو زرو کالى دې ترې نه وغواړى. نو بنى اِسرائيليان به دا څيزونه خپلو زامنو او لوڼو ته ورواغوندى. او مِصريان به لوټ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1549, 'Exodus 4:1', 'Exodus', 4, 1, '&nbsp;بيا موسىٰ مالِک خُدائ له جواب ورکړو، ”خو ګوره، کۀ بنى اِسرائيل په ما يقين ونۀ کړى او زما خبرې ته غوږ ونۀ نيسى نو زۀ څۀ وکړم کۀ هغوئ ووائى چې تۀ ما ته راڅرګند شوے نۀ يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1550, 'Exodus 4:2', 'Exodus', 4, 2, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”دا ستا په لاس کښې څۀ دى؟“ هغۀ ورته وفرمائيل، ”دا امسا ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1551, 'Exodus 4:3', 'Exodus', 4, 3, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”دا په زمکه وغورزوه.“ چې کله موسىٰ دا په زمکه وروغورزوله، نو يو مار ترې جوړ شو او موسىٰ ترې نه منډه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1552, 'Exodus 4:4', 'Exodus', 4, 4, '&nbsp;نو بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”ورټيټ شه او د لکۍ نه يې کلک راونيسه.“ نو موسىٰ ورټيټ شو او راوې نيولو او بيا ترې نه امسا جوړه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1553, 'Exodus 4:5', 'Exodus', 4, 5, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”هم داسې وکړه چې د بنى اِسرائيلو يقين راشى چې مالِک خُدائ د دوئ د پلار نيکۀ خُدائ پاک، د اِبراهيم، اِسحاق او د يعقوب خُدائ پاک تا ته راڅرګند شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1554, 'Exodus 4:6', 'Exodus', 4, 6, '&nbsp;مالِک خُدائ موسىٰ ته بيا وفرمائيل، ”خپل لاس چُوغې ته دننه کړه.“ نو موسىٰ لاس دننه کړو. او چې کله هغۀ لاس رابهر کړو، نو د هغۀ لاس د څرمنې په بيمارۍ پټ شوے وو، داسې سپين لکه واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1555, 'Exodus 4:7', 'Exodus', 4, 7, '&nbsp;بيا مالِک خُدائ وفرمائيل، ”لاس په چُوغه کښې بيا دننه کړه.“ نو هغۀ لاس دننه کړو او چې کله هغۀ دا ځل رابهر کړو، نو هم هغه شان روغ جوړ شو لکه څنګه چې يې نور بدن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1556, 'Exodus 4:8', 'Exodus', 4, 8, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”کۀ هغوئ په تا يقين ونۀ کړى يا د هغوئ په اولنۍ معجزه باندې يقين رانۀ شى، نو په دې بله به د دوئ يقين راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1557, 'Exodus 4:9', 'Exodus', 4, 9, '&nbsp;کۀ د دې دواړو معجزو باوجود هم هغوئ په تا يقين ونۀ کړى او کۀ هغوئ ستا د خبرې اورېدو نه اِنکار وکړى، نو لږې اوبۀ د نيل درياب نه راواخله او په اوچه زمکه يې توئ کړه. نو د اوبو نه به وينه جوړه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1558, 'Exodus 4:10', 'Exodus', 4, 10, '&nbsp;خو موسىٰ مالِک خُدائ ته وفرمائيل، ”اے زما مالِکه خُدايه، ما مۀ لېږه. زۀ صفا خبرې نۀ شم کولے نه د مخکښې نه په خبرو کولو کښې ښۀ وم او نه تاسو سره د خبرو کولو نه پس تکړه يم او ژبه مې هم انښلى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1559, 'Exodus 4:11', 'Exodus', 4, 11, '&nbsp;مالِک خُدائ هغۀ ته وفرمائيل، ”بنى آدم له ژبه څوک ورکوى؟ ګونګول او کڼول څوک کوى؟ نظر ورکول يا ړندول څوک کوى؟ دا زۀ، مالِک خُدائ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1560, 'Exodus 4:12', 'Exodus', 4, 12, '&nbsp;نو اوس لاړ شه. زۀ به ستا د خولې نه خبرې کوم او زۀ به تا ته وښايم چې څۀ به وائې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1561, 'Exodus 4:13', 'Exodus', 4, 13, '&nbsp;خو موسىٰ ورته وفرمائيل، ”اے زما مالِکه خُدايه، زۀ تا ته سوال کوم چې بل څوک ورولېږه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1562, 'Exodus 4:14', 'Exodus', 4, 14, '&nbsp;نو په دې باندې مالِک خُدائ موسىٰ ته غصه شو او وې فرمائيل، ”ستا ورور هارون، ليوى خو شته دے، ما ته پته ده چې هغه په خبرو کولو کښې تکړه دے. ګوره، اوس هغه تا سره مِلاوېدو له راروان دے او هغه به ستا په ليدو په زړۀ کښې خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1563, 'Exodus 4:15', 'Exodus', 4, 15, '&nbsp;تۀ به هغۀ ته هغه خبرې وښائې چې کومې به کوى. زۀ به ستاسو دواړو په خبرو کښې مدد وکړم او زۀ به تاسو دواړو ته ووايم چې څۀ به کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1564, 'Exodus 4:16', 'Exodus', 4, 16, '&nbsp;هغه به ستا د خبرو وياند وى او ستا په ځائ به خلقو ته خبرې کوى. نو تۀ به د هغۀ دپاره د خُدائ پاک په شان يې او ورته به ښائې چې څۀ به وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1565, 'Exodus 4:17', 'Exodus', 4, 17, '&nbsp;خپل ځان سره دا امسا يوسه، چې د دې سره به تۀ معجزې څرګندې کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1566, 'Exodus 4:18', 'Exodus', 4, 18, '&nbsp;بيا موسىٰ واپس خپل سخر يترو له لاړو او هغۀ ته يې وفرمائيل، ”ما له اجازت راکړه چې واپس مِصر ته لاړ شم چې وګورم چې زما خپلوان ژوندى دى او کۀ نه.“ يترو موسىٰ ته ووئيل، ”په خېر لاړ شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1567, 'Exodus 4:19', 'Exodus', 4, 19, '&nbsp;چې کله موسىٰ په ميديان کښې وو مالِک خُدائ هغۀ ته وفرمائيل، ”مِصر ته واپس لاړ شه، ځکه چې کومو خلقو تۀ وژلې هغه ټول مړۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1568, 'Exodus 4:20', 'Exodus', 4, 20, '&nbsp;نو موسىٰ خپله ښځه او زامن واخستل او په يو خر باندې يې سوارۀ کړل او د دوئ سره مِصر ته روان شو، هغه امسا يې هم يوړه چې خُدائ پاک ورته ښودلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1569, 'Exodus 4:21', 'Exodus', 4, 21, '&nbsp;مالِک خُدائ موسىٰ ته بيا وفرمائيل، ”اوس چې تۀ واپس مِصر ته روان يې، ګوره، چې د فِرعون په مخکښې هغه ټولې معجزې څرګندې کړې د کومو چې ما طاقت درکړے دے. خو زۀ به د هغۀ زړۀ سخت کړم او هغه به زما خلق تلو ته پرې نۀ ږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1570, 'Exodus 4:22', 'Exodus', 4, 22, '&nbsp;بيا تۀ هغۀ ته ووايه چې مالِک خُدائ فرمائى چې، بنى اِسرائيل ما ته د مشر زوئ په شان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1571, 'Exodus 4:23', 'Exodus', 4, 23, '&nbsp;ما تا ته وفرمائيل چې زما زوئ پرېږده چې لاړ شى، چې هغه زما عبادت وکړى، خو تا اِنکار وکړو. نو زۀ به اوس ستا مشر زوئ ووژنم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
