(1573, 'Exodus 4:27', 'Exodus', 4, 27, '&nbsp;بيا مالِک خُدائ هارون ته وفرمائيل، ”د موسىٰ سره مِلاوېدو له صحرا ته لاړ شه.“ نو هغه د هغۀ سره د خُدائ پاک په غرۀ کښې مِلاوېدو له لاړو، او چې کله هغه د هغۀ سره مِلاو شو، نو هغه يې ښُکل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1574, 'Exodus 4:28', 'Exodus', 4, 28, '&nbsp;بيا موسىٰ هارون ته هغه هر څۀ وفرمائيل څۀ چې مالِک خُدائ د فرمائيلو دپاره لېږلے وو، هغۀ د هغه معجزو په حقله هم هغۀ ته وفرمائيل د کومو چې مالِک خُدائ د کولو حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1575, 'Exodus 4:29', 'Exodus', 4, 29, '&nbsp;نو موسىٰ او هارون مِصر ته لاړل او د بنى اِسرائيلو ټول مشران يې په يو ځائ راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
