(1580, 'Exodus 5:3', 'Exodus', 5, 3, '&nbsp;موسىٰ او هارون ورته وفرمائيل، ”د عبرانيانو خُدائ پاک مونږ ته په خپله راڅرګند شوے دے. مونږ پرېږده چې په صحرا کښې درې ورځې سفر وکړُو چې مالِک خُدائ زمونږ خُدائ پاک ته قربانۍ پېش کړُو. کۀ مونږ داسې ونۀ کړل، نو هغه به مونږ په وبا يا په جنګ ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1581, 'Exodus 5:4', 'Exodus', 5, 4, '&nbsp;فِرعون موسىٰ او هارون ته ووئيل، ”تاسو ولې دا خلق د خپل کار نه وباسئ؟ پرېږدئ چې هم دغه کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1582, 'Exodus 5:5', 'Exodus', 5, 5, '&nbsp;ګورئ، تاسو خلق د مِصريانو نه ډېر زيات شوى يئ. او اوس تاسو دا هم غواړئ چې دوئ کار بس کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1583, 'Exodus 5:6', 'Exodus', 5, 6, '&nbsp;هم په هغه ورځ فِرعون د دوئ سختو مِصريانو مشرانو او بنى اِسرائيلو آفسرانو له حُکم ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1584, 'Exodus 5:7', 'Exodus', 5, 7, '&nbsp;”د خښتو جوړولو دپاره خلقو ته بوس ورکول بند کړئ. دوئ لېږئ چې په خپله يې ځان له راغونډوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1585, 'Exodus 5:8', 'Exodus', 5, 8, '&nbsp;او هم هغه هومره خَښتې ترې نه غواړئ چې څومره يې مخکښې جوړولې، تاسو پرې يوه هم مۀ کموئ. دوئ خو کار نۀ کوى، نو ځکه دوئ هر وخت مِنتُونه کوى چې زۀ دوئ پرېږدم چې لاړ شى او خپل خُدائ پاک ته قربانۍ پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1586, 'Exodus 5:9', 'Exodus', 5, 9, '&nbsp;په دې خلقو د مخکښې نه نور هم سخت کار کوئ او په داسې کار يې آخته کړئ چې د دې دروغو خبرو اورېدو وخت هم ورسره نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1587, 'Exodus 5:10', 'Exodus', 5, 10, '&nbsp;د هغوئ نه سخت کار اخستونکى مشران او د دوئ آفسران بهر لاړل او بنى اِسرائيلو ته يې ووئيل، ”فِرعون وئيلى دى چې هغه به تاسو له نور بوس نۀ درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1588, 'Exodus 5:11', 'Exodus', 5, 11, '&nbsp;هغه وائى چې تاسو ځئ او چې چرته هم تاسو د خپلو ځانونو دپاره بوس راپېدا کولے شئ نو پېدا يې کړئ، خو د خښتو د جوړولو په شمېر کښې به کمے نۀ راولئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1589, 'Exodus 5:12', 'Exodus', 5, 12, '&nbsp;نو خلق د مِصر ټول مُلک کښې خوارۀ شول چې بوس راجمع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1590, 'Exodus 5:13', 'Exodus', 5, 13, '&nbsp;د هغوئ سختو مشرانو په دوئ زور راوړلو چې هره ورځ به هم هغه هومره خَښتې جوړوى چې څومره يې مخکښې جوړولې چې کله هغوئ ته بوس مِلاوېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1591, 'Exodus 5:14', 'Exodus', 5, 14, '&nbsp;د هغوئ سختو مِصريانو مشرانو بنى اِسرائيل آفسران وهل، کوم چې هغوئ د دې کار مشران مقرر کړى وُو. ورته يې وئيل، ”تاسو ولې هم هغه هومره خَښتې نۀ جوړَوئ لکه چې څومره تاسو مخکښې جوړولې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1592, 'Exodus 5:15', 'Exodus', 5, 15, '&nbsp;نو د بنى اِسرائيلو آفسران راغلل او فِرعون ته يې فرياد وکړو، ”بادشاه سلامت، زمونږ سره داسې ولې کيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1593, 'Exodus 5:16', 'Exodus', 5, 16, '&nbsp;مونږ له بوس نۀ راکوى، خو بيا هم هغوئ د خښتو جوړولو حُکم راکوى او ګوره، مونږ وهلے هم شُو. خو دا ستا د خپلو خلقو غلطى ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1594, 'Exodus 5:17', 'Exodus', 5, 17, '&nbsp;فِرعون ورته ووئيل، ”تاسو ناراسته يئ او کار کول نۀ غواړئ، نو دا ځکه تاسو مِنت کوئ چې زۀ تاسو تلو ته پرېږدم چې مالِک خُدائ ته قربانۍ پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1595, 'Exodus 5:18', 'Exodus', 5, 18, '&nbsp;اوس واپس کار له لاړ شئ. تاسو له به هغوئ لږ بوس هم نۀ درکوى، خو اوس به خامخا هم هغه هومره خَښتې جوړَوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1596, 'Exodus 5:19', 'Exodus', 5, 19, '&nbsp;د بنى اِسرائيلو آفسرانو ته پته ولګېده چې دوئ په بد حالت کښې دى، چې کله هغوئ ته ووئيلے شول چې دوئ به هره ورځ هم هغه هومره خَښتې جوړوى چې څومره يې مخکښې جوړولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1597, 'Exodus 5:20', 'Exodus', 5, 20, '&nbsp;چې څنګه دوئ د فِرعون د دربار نه راووتل، نو دوئ د موسىٰ او هارون سره مِلاو شول، ځکه چې هغوئ د دوئ اِنتظار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1598, 'Exodus 5:21', 'Exodus', 5, 21, '&nbsp;دوئ موسىٰ او هارون ته ووئيل، ”مالِک خُدائ دې په خپله ستاسو عدالت وکړى او سزا دې درکړى ځکه چې تاسو د فِرعون او د هغۀ د درباريانو په زړُونو کښې نفرت پېدا کړے دے. تاسو هغۀ له زمونږ د قتل بهانه ورکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1599, 'Exodus 5:22', 'Exodus', 5, 22, '&nbsp;بيا موسىٰ مالِک خُدائ ته واپس وګرځېدو او ورته يې وفرمائيل، ”مالِکه خُدايه، تۀ د دې خلقو سره ولې بد سلوک کوې؟ تا زۀ ولې دلته رالېږلے يم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1600, 'Exodus 5:23', 'Exodus', 5, 23, '&nbsp;ما چې کله هم د فِرعون سره ستا په نوم خبرې کړې دى، نو هغۀ د دوئ سره بد سلوک کړے دے. او تا د خپلو خلقو مدد نۀ دے کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');